import Foundation
import Testing
@testable import RHCrypto

/// contracts/vectors/jcs.json, generated by RHServer. The client must pass scope "protocol".
private struct JCSVectorFile: Decodable {
    let version: Int
    let vectors: [JCSVector]
}

private struct JCSVector: Decodable {
    let name: String
    let scope: String
    let input: String
    let expected: String?
    let expected_hex: String?
    let expected_sha256: String?
    let expect_error: Bool?
}

struct JCSVectorTests {
    @Test func protocolScopeVectors() throws {
        let file = try JSONDecoder().decode(JCSVectorFile.self, from: ContractsLocation.data("vectors/jcs.json"))
        #expect(file.version == 1)
        // Protocol scope is mandatory; rejections from any scope must hold too, since the
        // client's parser is stricter than full JCS (no fractions at all).
        let vectors = file.vectors.filter { $0.scope == "protocol" || $0.expect_error == true }
        #expect(!vectors.isEmpty, "no protocol-scope vectors in contracts/vectors/jcs.json")
        for vector in vectors {
            if vector.expect_error == true {
                #expect(throws: JCSError.self, "\(vector.name): must be rejected") {
                    try JCS.canonicalize(jsonText: vector.input)
                }
                continue
            }
            let expected = try #require(vector.expected, "\(vector.name): no expected")
            let canonical = try JCS.canonicalize(jsonText: vector.input)
            #expect(canonical == Array(expected.utf8), "\(vector.name): canonical bytes differ")
            if let hex = vector.expected_hex {
                #expect(canonical.map { String(format: "%02x", $0) }.joined() == hex.lowercased(), "\(vector.name): hex differs")
            }
            if let digest = vector.expected_sha256 {
                #expect(sha256Hex(canonical) == digest, "\(vector.name): sha256 differs")
            }
        }
    }
}
